package com.stock.dividend.ui.component

// Generated from TradingView China scanner, sorted by market cap, on 2026-05-11.
// Maps all 5275 China common stocks with available logo ids to TradingView logo ids.
// Exchanges in source data: SSE, SZSE.
internal const val A_SHARE_LOGO_ID_COUNT: Int = 5275

internal fun aShareLogoIdForCode(code: String): String? = when (code.take(3)) {
    "000" -> aShareLogoId000(code)
    "001" -> aShareLogoId001(code)
    "002" -> aShareLogoId002(code)
    "003" -> aShareLogoId003(code)
    "180" -> aShareLogoId180(code)
    "200" -> aShareLogoId200(code)
    "201" -> aShareLogoId201(code)
    "300" -> aShareLogoId300(code)
    "301" -> aShareLogoId301(code)
    "302" -> aShareLogoId302(code)
    "508" -> aShareLogoId508(code)
    "600" -> aShareLogoId600(code)
    "601" -> aShareLogoId601(code)
    "603" -> aShareLogoId603(code)
    "605" -> aShareLogoId605(code)
    "688" -> aShareLogoId688(code)
    "900" -> aShareLogoId900(code)
    else -> null
}

